#!/usr/bin/env python3
"""Gate C15 step 3: number check for Sections III, IV, VI, VII, VIII (whole files) and the changed lines of Sections I and V (git diff of the C15 install commit).
Generic rule (same as C14): each number token is matched by string, or by rounding to the digits printed, against paper/support/RESULTS_FACTS.md; a second column says whether the
token is also in EVIDENCE_EXTRACT.md. Then named confirmations are computed from the CSVs/extract and compared with the text. Writes results/analysis/consolidation/C15_NUMCHECK.md."""
import csv, glob, os, re, subprocess, sys, statistics as st
sys.path.insert(0, "tests")
facts = open("paper/support/RESULTS_FACTS.md").read()
extract = open("results/analysis/consolidation/EVIDENCE_EXTRACT.md").read()
def nums(t): 
    r = set()
    for x in re.findall(r"[+\u2212-]?\d[\d,]*\.?\d*(?:e[+-]?\d+)?", t):
        try: r.add(float(x.replace(",", "").replace("\u2212", "-")))
        except ValueError: pass
    return r
FN, EN = nums(facts), nums(extract)
def clean(l):
    l = re.sub(r"(?<!\\)%.*$", "", l).replace("{,}", ",")
    return re.sub(r"\\(?:cite|ref|label|input|texttt|url|includegraphics|autoref|eqref)\w*\*?(?:\[[^\]]*\])*\{[^}]*\}", " ", l)
def toks(path, only=None):
    out = []
    for n, l in enumerate(open(path), 1):
        if only is not None and n not in only: continue
        c = clean(l)
        for m in re.finditer(r"(?<![A-Za-z\\{])(\d[\d,]*(?:\.\d+)?)(?:\\,|~)?(\\%|\\times|x)?", c):
            tok = m.group(1).rstrip(",")
            if re.match(r"(19|20)\d\d$", tok) and not m.group(2): continue
            out.append((n, tok, m.group(2) or "", l.strip()))
    return out
def match(tok, unit, pool, text):
    x = float(tok.replace(",", "")); d = len(tok.split(".")[1]) if "." in tok else 0
    if re.search(rf"(?<![\d.]){re.escape(tok)}(?!\d)", text): return "string"
    for f in pool:
        if round(abs(f), d) == round(x, d): return "rounded"
        if unit == "\\%" and round(abs(f) * 100, d) == round(x, d): return "fraction x100"
    return None
def changed(path):
    d = subprocess.check_output(["git", "diff", "-U0", "HEAD~1", "HEAD", "--", path]).decode()
    s = set()
    for m in re.finditer(r"^@@ -\S+ \+(\d+)(?:,(\d+))? @@", d, re.M):
        a, n = int(m.group(1)), int(m.group(2) or 1); s |= set(range(a, a + n))
    return s
FILES = [("paper/section3_background.tex", None), ("paper/section4_design.tex", None), ("paper/section6_speculation.tex", None), ("paper/section7_threshold.tex", None), ("paper/section8_pitfalls.tex", None),
         ("paper/section1_introduction.tex", changed("paper/section1_introduction.tex")), ("paper/section5_protocol.tex", changed("paper/section5_protocol.tex"))]
md = ["# C15 number check (generated by `tests/c15_numcheck.py`)", "",
      "Rule as C14: a token is MATCH if it equals a number in `paper/support/RESULTS_FACTS.md` as a string or after rounding to its printed digits (fraction x100 for percentages). Integers below 20 without a unit are `small` (counts, section numbers; matches are ambiguous). `also in extract` = found in `EVIDENCE_EXTRACT.md` when not in RESULTS_FACTS. Cite keys, labels, refs and `\\texttt` evidence ids are removed first.", ""]
NF = []
for path, only in FILES:
    t = toks(path, only)
    md += [f"## {os.path.basename(path)}" + (f" (changed lines only: {len(only)} lines)" if only is not None else ""), "", f"{len(t)} tokens.", "", "| line | number | status | context |", "|---|---|---|---|"]
    nfl = []
    for n, tok, unit, ctx in t:
        small = float(tok.replace(",", "")) < 20 and "." not in tok and not unit
        m = match(tok, unit, FN, facts)
        if m is None:
            e = match(tok, unit, EN, extract)
            s = ("also in extract (" + e + ")") if e else "NOT FOUND"
        else: s = "MATCH (" + m + ")"
        if small and m: continue
        if m is None: nfl.append((n, tok + unit, s, ctx))
        elif not small and "--md-all" in sys.argv: md.append(f"| {n} | {tok}{unit} | {s} | {ctx[:100].replace('|','/')} |")
    md += [f"| {n} | {t_} | {s} | {c[:110].replace('|', '/')} |" for n, t_, s, c in nfl]
    md += ["", f"Not matched in RESULTS_FACTS: {len(nfl)} (of which NOT FOUND anywhere: {sum(1 for x in nfl if x[2] == 'NOT FOUND')}).", ""]
    NF += [(path, *x) for x in nfl]
# ---------------- named confirmations
def ev(i):
    m = re.search(rf"^\| `{re.escape(i)}` \| (.*?) \| `", extract, re.M); return m.group(1)
def g(i, k): return float(re.search(rf"{k}=([+-]?[\d,.]+)", ev(i)).group(1).replace(",", ""))
mc = {r["workload"] + "|" + r["arm"]: r for r in csv.DictReader(open("results/analysis/gate_e/e4/mechanism.csv"))}
rows = []
def chk(sec, claim, computed, ok, src): rows.append((sec, claim, computed, "MATCH" if ok else "**MISMATCH**", src))
_r = mc["stencil|C6-W512"]; _d = float(_r["fault_already_resident"]) / float(_r["far_frac_distinct"])
c1, c6 = g("E4.mech.stencil.C1", "demand_faults"), g("E4.mech.stencil.C6-W512", "demand_faults")
chk("VI", "1.3% more demand faults (C6-W512 vs C1)", f"{100*(c6/c1-1):.2f}%", round(100 * (c6 / c1 - 1), 1) == 1.3, "E4.mech.stencil.C6-W512, E4.mech.stencil.C1")
FR = {int(r["threshold"]): float(r["D"]) for r in csv.DictReader(open("results/analysis/gate_e/e5/fault_reduction.csv"))}; d51, d75, d100 = FR[51], FR[75], FR[100]
chk("VI", "40.1% (E5.D(51)), 53.4% (E5.D(75)), -2.2% (E5.D(100))", f"{100*d51:.3f}%, {100*d75:.3f}%, {100*d100:.3f}% (unrounded D from fault_reduction.csv; the extract shows -0.0215, which would round to -2.2 only by double rounding)", round(100 * d51, 1) == 40.1 and round(100 * d75, 1) == 53.4 and round(100 * d100, 1) == -2.2, "E5.D(51), E5.D(75), E5.D(100)")
f5, f4 = g("E5.mech.t51.C7W512", "far_frac"), g("E4.mech.stencil.C7-W512", "far_frac")
chk("VI", "2.07% of distinct pages (worker first, prefetcher on)", f"E5 t51 C7W512 far_frac {100*f5:.2f}%; E4 C7-W512 {100*f4:.2f}%; E4 C7-W1 {100*g('E4.mech.stencil.C7-W1','far_frac'):.2f}%", round(100 * f5, 2) == 2.07, "E5.mech.t51.C7W512 (E4.mech.stencil.C7-W1 also 2.07%; E4 C7-W512 is 2.04%)")
rem = [float(re.search(r"removed=([\d.]+)", ev(i)).group(1)) for i in ("E3b.stencil.C6.residual", "E3b.stencil.C7.residual", "E3b.graphbfs.C6.residual")]
chk("VI", "78-88% of the residual removed", ", ".join(f"{x:.1f}%" for x in rem), round(min(rem)) == 78 and round(max(rem)) == 88, "E3b.stencil.C6/C7.residual, E3b.graphbfs.C6.residual")
ns = [float(re.search(r"fast0=\S+ \(([\d.]+) ns/fault", ev(i)).group(1)) for i in ("E3b.stencil.C6.residual", "E3b.stencil.C7.residual", "E3b.graphbfs.C6.residual")]
ns2 = [g(i, "residual_per_fault") for i in ("E1b.stencil.C64096-C1", "E1b.graphbfs.C64096-C1")]
chk("VI", "140-167 ns per fault (lookup)", "E3b fast0: " + ", ".join(f"{x:.1f}" for x in ns) + "; E1b residual_per_fault: " + ", ".join(f"{x:.0f}" for x in ns2), round(min(ns)) == 140 and round(max(ns)) == 167, "E3b.*.residual")
e = ev("E4.mech.stencil.C7-W512"); chk("VI", "about 2,200 enqueued, 0 drops (C7-W512)", f"enqueued {g('E4.mech.stencil.C7-W512','enqueued'):,.0f}, drops {g('E4.mech.stencil.C7-W512','drops'):.0f}", abs(g("E4.mech.stencil.C7-W512", "enqueued") - 2200) < 50 and g("E4.mech.stencil.C7-W512", "drops") == 0, "E4.mech.stencil.C7-W512")
v = ev("E1PartB.stencil.D5"); c1d, c6d = float(re.search(r"C1=([\d.]+)", v).group(1)), float(re.search(r"C6L4096=([\d.]+)", v).group(1))
w = ev("E1PartB.stencil.svc_minus_D3_D4"); dsvc = float(re.search(r"C1_minus_C6=([+-][\d.]+)", w).group(1))
chk("VI", "D5 1.60 -> 0.91 s (C6-L4096, E1)", f"{c1d:.4f} -> {c6d:.4f}", round(c1d, 2) == 1.60 and round(c6d, 2) == 0.91, "E1PartB.stencil.D5")
chk("VI", "+0.48 s (service minus D3, D4; C6-L4096, E1)", f"{-dsvc:+.4f} s (C6 minus C1)", round(-dsvc, 2) == 0.48, "E1PartB.stencil.svc_minus_D3_D4")
mde = [float(re.search(r"mde_family_pct=([\d.]+)", ev(f"E7.B.{w}.stock-t0_vs_stock-t51")).group(1)) for w in ("stencil8k", "sweep4k", "cufft")]
chk("VII", "7-12% MDEs for three short workloads (family alpha)", "Stencil-8K, Sweep-4K, cuFFT: " + ", ".join(f"{x:.2f}%" for x in mde), round(min(mde)) == 7 and round(max(mde)) == 12, "E7.B.stencil8k/sweep4k/cufft")
chk("VII", "0.86% (GraphBFS t0 MDE, delta -0.26%)", f"mde_family {g('E7.B.graphbfs.stock-t0_vs_stock-t51','mde_family_pct'):.2f}%, delta {float(re.search(r'base=([+-][\d.]+)%', ev('E7.B.graphbfs.stock-t0_vs_stock-t51')).group(1)):+.2f}%", round(g("E7.B.graphbfs.stock-t0_vs_stock-t51", "mde_family_pct"), 2) == 0.86, "E7.B.graphbfs.stock-t0_vs_stock-t51")
h0, h51 = g("E9.cell.ov_k1.t0", "htod_gib"), g("E9.cell.ov_k1.t51", "htod_gib")
chk("VII", "129.8 GiB vs 3.96 GiB, factor 32.8 (ov K=1)", f"{h0:.3f} / {h51:.3f} = {h0/h51:.2f}", round(h0, 1) == 129.8 and round(h51, 2) == 3.96 and round(h0 / h51, 1) == 32.8, "E9.cell.ov_k1.t0, .t51")
vol = [g(f"E9.cell.ov_k{k}.t{t}", "htod_gib") for k in (64, 512) for t in (0, 51)]
chk("VII", "about 72 GiB at K >= 64, same at both thresholds", ", ".join(f"{x:.2f}" for x in vol), all(abs(x - 72) < 0.5 for x in vol), "E9.cell.ov_k64/ov_k512")
runs = list(csv.DictReader(open("results/analysis/gate_e/e9/e9_runs.csv")))
cell = {}
for r in runs:
    if r.get("report_cpu_faults", "") != "": cell.setdefault((r["workload"], int(r["threshold"])), []).append(float(r["report_cpu_faults"]))
rat = []
for (wl, t), v in cell.items():
    if t == 51 and (wl, 0) in cell: rat += [a / b for a in v for b in cell[(wl, 0)]]
chk("VII", "CPU faults six times less often at threshold 0 in every traced run", f"per-run ratios t51/t0 (all pairings, {len(rat)}): min {min(rat):.2f}, max {max(rat):.2f}; medians 6.00x (E9.ratio.cpu_faults_t51_over_t0)", abs(min(rat) - 6) < 0.01 and abs(max(rat) - 6) < 0.01, "e9_runs.csv report_cpu_faults; E9.ratio.cpu_faults_t51_over_t0; E9.cpu_phase.fill_only")
z7 = [r for r in csv.DictReader(open("results/analysis/gate_e/h2/h2_z.csv")) if r["id"] == "Z7"][0]["detail"]
m = re.search(r"difference ([+-][\d.]+) points, 95% CI \[([+-][\d.]+), ([+-][\d.]+)\]", z7)
chk("VII", "199.7 percentage points, CI 198.1 to 201.7", f"{m.group(1)} [{m.group(2)}, {m.group(3)}]", (round(float(m.group(1)), 1), round(float(m.group(2)), 1), round(float(m.group(3)), 1)) == (199.7, 198.1, 201.7), "H2.Z7, h2_z.csv")
dd = []
for k in (1, 8, 64, 512):
    h = float(re.search(r"delta_pct\S*=([+-][\d.]+)", ev(f"H2.managed_k{k}.t0_vs_t51")).group(1)); e8 = float(re.search(r"delta_pct\S*=([+-][\d.]+)", ev(f"E8.in.K{k}.stock-t0_vs_stock-t51")).group(1)); dd.append((k, h, e8, abs(h - e8)))
chk("VII", "H2 managed +3.92, -1.49, -9.99, -7.19 within a point of E8", "; ".join(f"K{k}: H2 {h:+.2f} vs E8 {e:+.2f} (|diff| {d:.2f})" for k, h, e, d in dd), [round(x[1], 2) for x in dd] == [3.92, -1.49, -9.99, -7.19] and max(x[3] for x in dd) < 1, "H2.managed_k*, E8.in.K*")
mal = [float(re.search(r"delta_pct\S*=([+-][\d.]+)", ev(f"H2.malloc_k{k}.t0_vs_t51")).group(1)) for k in (1, 8, 64, 512)]
chk("VII", "HMM +203.65, +50.39, -24.66, -19.56", ", ".join(f"{x:+.2f}" for x in mal), [round(x, 2) for x in mal] == [203.65, 50.39, -24.66, -19.56], "H2.malloc_k*")
chk("VII", "T4 12 of 14 faster, none slower", ev("T4.B.count"), "holm_significant_faster=12" in ev("T4.B.count") and "holm_significant_slower=0" in ev("T4.B.count") and "tests=14" in ev("T4.B.count"), "T4.B.count")
cat = open("results/analysis/ARTIFACT_CATALOG.md").read()
ft = cat.split("| family | entries")[1].split("\n\n")[0].split("\n")[2:]
catfam = {}
for l in ft:
    if l.startswith("|"):
        c = l.split("|"); catfam[re.sub(r"[*_()]|uncategorised: a genuine outlier|\(new, C6\)", "", c[1]).strip()] = sorted({int(x) for x in re.findall(r"#(\d+)", c[2])})
s8 = open("paper/section8_pitfalls.tex").read()
tab = s8.split("Family & Entries")[1].split("\\end{tabular}")[0]
texfam = []
for l in tab.split("\\\\")[1:]:
    parts = [p.strip() for p in l.replace("\\toprule", "").replace("\\midrule", "").replace("\\bottomrule", "").split("&")]
    if len(parts) == 3 and parts[2].strip().isdigit(): texfam.append((parts[0], sorted(int(x) for x in re.findall(r"\d+", parts[1])), int(parts[2])))
for name, ents, n in texfam:
    key = "" if name.lower().startswith("uncategorised") and "" in catfam else next((k for k in catfam if k.lower().startswith(name.lower()[:18])), None)
    chk("VIII", f"family table row: {name}", f"tex {ents} n={n}; catalog {catfam.get(key)}", key is not None and catfam[key] == ents and len(ents) == n, "ARTIFACT_CATALOG.md families table")
chk("VIII", "family table total", f"tex rows {len(texfam)}, sum n = {sum(n for _, _, n in texfam)}; catalog sum {sum(len(v) for v in catfam.values())}", sum(n for _, _, n in texfam) == 31 == sum(len(v) for v in catfam.values()), "ARTIFACT_CATALOG.md")
chk("VIII", "'103 days' for #13", re.search(r"103 days[^\n]*", cat).group(0)[:110] + " | catalog: 2026-06-13 -> 2026-09-24 = " + str((__import__('datetime').date(2026, 9, 24) - __import__('datetime').date(2026, 6, 13)).days) + " days", (__import__('datetime').date(2026, 9, 24) - __import__('datetime').date(2026, 6, 13)).days == 103, "ARTIFACT_CATALOG.md #13 (and C14 RESULTS_FACTS)")
agg = catfam["Aggregation-level mismatch"]
chk("VIII", "'seven had reached a reported figure' of nine aggregation entries", f"catalog 'Scope of the observation': #7, #8, #9, #13, #16, #17, #18 = 7 of {len(agg)}", "(#7, #8, #9, #13, #16, #17, #18)" in cat and len(agg) == 9, "ARTIFACT_CATALOG.md")
chk("VIII", "four in-gate catches (#10, #21, #25, #30)", "prereg column (families table): " + ", ".join("#" + str(x) for x in sorted({int(x) for l in ft if l.startswith('|') for x in re.findall(r'#(\d+)', l.split('|')[5])})), sorted({int(x) for l in ft if l.startswith("|") for x in re.findall(r"#(\d+)", l.split("|")[5])}) == [10, 21, 25, 30], "ARTIFACT_CATALOG.md families table (column: caught by a pre-registered check)")
chk("VI/VII", "1,125,000 distinct pages of Stencil-24K", f"far / far_frac_distinct (E4 C6-W512) = {_d:,.0f}", abs(_d - 1125000) < 1000, "e4/mechanism.csv")
chk("VI", "about 2,200 enqueued (token 2{,}200)", f"E4.mech.stencil.C7-W512 enqueued = {g('E4.mech.stencil.C7-W512','enqueued'):,.0f} (token is rounded; not an exact number in the facts file)", True, "E4.mech.stencil.C7-W512")
md += ["## Named confirmations", "", "| section | claim | computed | status | source |", "|---|---|---|---|---|"] + [f"| {a} | {b} | {c.replace('|','/')} | {d} | {e} |" for a, b, c, d, e in rows] + [""]
open("results/analysis/consolidation/C15_NUMCHECK.md", "w").write("\n".join(md))
print(len(NF), "unmatched tokens;", sum(1 for r in rows if "MISMATCH" in r[3]), "mismatch of", len(rows))
for r in rows:
    if "MISMATCH" in r[3]: print(r[:3])
